        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    opp_c = sum(1 for _, b in history if b == 'C')
    my_c = sum(1 for a, _ in history if a == 'C')

    def opp_coop_rate(start=0):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if history[i][1] == 'C':
                cnt += 1
        if tot == 0:
            return 0.5
        return cnt / tot

    recent_len = min(10, n)
    recent_opp = opp_coop_rate(n - recent_len)
    overall_opp = opp_coop_rate(0)

    last_me, last_opp = history[-1]

    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'

