    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    cooperation_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cooperation_streak += 1
        else:
            break

    score_diff = my_score - opp_score

    rounds_left = 100 - n

    if recent_opp <= 0.15 and defection_streak >= 2:
        return 'D'

    if rounds_left <= 2:
        if last_opp == 'C' and recent_opp > 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if rounds_left <= 6:
        if recent_opp >= 0.7:
            return 'C'
        if recent_opp <= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 3:
        if history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            if rng.random() < 0.9:
                return 'D'
            return 'C'

    if last_opp == 'C' and recent_opp >= 0.6:
        return 'C'

    if overall_opp >= 0.75 and recent_opp >= 0.5:
        return 'C'

    if last_opp == 'D':
        if recent_opp >= 0.55:
            return 'C'
        if defection_streak >= 3:
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        if defection_streak >= 2:
            if rng.random() < 0.7:
